// SoundPass.cs - drop-in sound effect player for packs generated by soundpass.
//
// Setup: render the pack into Assets/Resources/SoundPass (manifest.json + .wav files).
// Usage:
//   SoundPass.Play("coin");
//   SoundPass.Play("combo", level: comboCount - 1);   // ladder sounds
//   SoundPass.Play("hit", volume: 0.6f);
//   SoundPass.Volume = 0.8f;                           // master SFX volume (0..1)
//   SoundPass.Muted = true;
//   SoundPass.Output = mySfxMixerGroup;                // optional AudioMixer routing
//
// No setup scene object is needed: the player creates itself on first use and survives
// scene loads. Works with Unity 2019.4+.
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Audio;

public class SoundPass : MonoBehaviour
{
#pragma warning disable 0649 // fields are filled by JsonUtility
    [System.Serializable]
    class Sound
    {
        public string id;
        public string category;
        public bool ladder;
        public string[] files;
    }

    [System.Serializable]
    class Manifest
    {
        public string palette;
        public Sound[] sounds;
    }
#pragma warning restore 0649

    const string Folder = "SoundPass"; // under any Resources folder
    const int Voices = 16;
    const float RepeatGuardSeconds = 0.03f;

    public static float Volume = 1f;
    public static bool Muted;
    public static AudioMixerGroup Output;

    static SoundPass instance;

    readonly Dictionary<string, AudioClip[]> clips = new Dictionary<string, AudioClip[]>();
    readonly Dictionary<string, bool> ladders = new Dictionary<string, bool>();
    readonly Dictionary<string, int> lastVariant = new Dictionary<string, int>();
    readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();
    AudioSource[] sources;
    int next;

    static SoundPass Instance
    {
        get
        {
            if (instance == null)
            {
                var go = new GameObject("SoundPass");
                DontDestroyOnLoad(go);
                instance = go.AddComponent<SoundPass>();
                instance.Load();
            }
            return instance;
        }
    }

    /// <summary>Load clips now instead of on the first Play (avoids a hitch).</summary>
    public static void Preload()
    {
        var _ = Instance;
    }

    /// <summary>Play a sound by id. Variants are picked at random without immediate repeats.</summary>
    /// <param name="level">For ladder sounds (combo, star): which step to play, from 0.</param>
    /// <param name="pitchJitter">Random pitch spread for non-ladder sounds (0.03 = +/-3%).</param>
    public static void Play(string id, float volume = 1f, int level = 0, float pitchJitter = 0.03f)
    {
        if (Muted) return;
        Instance.PlayInternal(id, volume, level, pitchJitter);
    }

    public static bool Has(string id)
    {
        return Instance.clips.ContainsKey(id);
    }

    void Load()
    {
        sources = new AudioSource[Voices];
        for (int i = 0; i < Voices; i++)
        {
            var s = gameObject.AddComponent<AudioSource>();
            s.playOnAwake = false;
            s.spatialBlend = 0f;
            sources[i] = s;
        }

        var text = Resources.Load<TextAsset>(Folder + "/manifest");
        if (text == null)
        {
            Debug.LogWarning("SoundPass: Resources/" + Folder + "/manifest.json not found. Did you run `soundpass pack`?");
            return;
        }
        var manifest = JsonUtility.FromJson<Manifest>(text.text);
        foreach (var s in manifest.sounds)
        {
            var arr = new AudioClip[s.files.Length];
            for (int i = 0; i < arr.Length; i++)
            {
                var name = System.IO.Path.GetFileNameWithoutExtension(s.files[i]);
                arr[i] = Resources.Load<AudioClip>(Folder + "/" + name);
                if (arr[i] == null) Debug.LogWarning("SoundPass: missing clip " + name);
            }
            clips[s.id] = arr;
            ladders[s.id] = s.ladder;
        }
    }

    void PlayInternal(string id, float volume, int level, float pitchJitter)
    {
        AudioClip[] arr;
        if (!clips.TryGetValue(id, out arr) || arr.Length == 0)
        {
            Debug.LogWarning("SoundPass: no sound '" + id + "'");
            return;
        }

        // The same sound twice in the same instant only sounds louder (and can clip).
        float last;
        if (lastPlayed.TryGetValue(id, out last) && Time.unscaledTime - last < RepeatGuardSeconds) return;
        lastPlayed[id] = Time.unscaledTime;

        bool ladder = ladders[id];
        int idx;
        if (ladder)
        {
            idx = Mathf.Clamp(level, 0, arr.Length - 1);
        }
        else
        {
            idx = Random.Range(0, arr.Length);
            int prev;
            if (arr.Length > 1 && lastVariant.TryGetValue(id, out prev) && prev == idx) idx = (idx + 1) % arr.Length;
            lastVariant[id] = idx;
        }
        if (arr[idx] == null) return;

        var src = sources[next];
        next = (next + 1) % sources.Length;
        src.outputAudioMixerGroup = Output;
        src.pitch = ladder ? 1f : 1f + Random.Range(-pitchJitter, pitchJitter);
        src.PlayOneShot(arr[idx], Mathf.Clamp01(volume) * Volume);
    }
}
